// === Tab: mySketch ===
let n = 7;
let m = 360;

int [][][] x = new Array(n)[m][8];
int [][][] l = new Array(n)[m][8];
int [][][] sw = new Array(n)[m][8];
color [][][] c = new Array(n)[m][8];
let rgb = new Array(6);

float [] xp = new Array(n);
float [] yp = new Array(n);

float [] r = new float [n];
float [] cc = new Array(n);

function setup(){
  createCanvas(800, 800);
  background(0);
  colorMode(HSB,360,100,100);
  strokeWeight(10);

  stroke(255,255,0);
  for(j=0; j<n; j++){
    xp[j]=random(100,width-100);
    yp[j]=random(100,height-100);
    r[j]=random(30,120);
    cc[j]=random(360);
   for(i = 0; i<m; i++){
     for(k = 0; k < 8; k++){
       x[j][i][k]=k*70+int(random(-10,10));
       l[j][i][k]=int(random(5,40));
       sw[j][i][k] = int(random(0.25,1.5));
       c[j][i][k] = color(cc[j]+random(-10,10),random(80,100),random(80,100));
     }
   }
  }

   rgb[0]="#E9FA0A";
   rgb[1]="#FFFFFF";
   rgb[2]="#F2D10F";
   rgb[3]="#F9FA14";
   rgb[4]="#FFC905";
   rgb[5]="#D1A60B"; 

}



function draw(){
    fill(0,30);
    rect(0,0,width,height);
    noStroke();
	  for(i=0; i<n; i++){
			pushMatrix();
			translate(xp[i],yp[i]);
			fill(cc[i],40+60*sq(sin(PI/800*frameCount)),40+60*sq(sin(PI/800*frameCount)));
      ellipse(0,0,r[i],r[i]);
			popMatrix();
		}

	stroke(0);
    for(i=0; i<n; i++){
      pushMatrix();
      translate(xp[i],yp[i]);
      //ellipse(0,0,100,100);
      stroke(255,255,0);
      for(alpha=0; alpha <m; alpha+=3){
        rotate(radians(360*3/m));
        for(k =0; k < 8; k++){
          x[i][alpha][k]+=5;
          if ((x[i][alpha][k])+(l[i][alpha][k]) > 700){
            x[i][alpha][k] = 0;
          }
          strokeWeight(1);
          stroke(c[i][alpha][k],100-10*k);
          line(x[i][alpha][k],0,x[i][alpha][k]+l[i][alpha][k],0);
        }
      }

      popMatrix();
    }




}

